    for g1 in range(2, 1000):
        for g2 in range(2, 1000):
            num4 = g1 + g2 + 840
            # g3 must be a divisor of num4 and g4 = num4 / g3 > 1
            # So g3 <= num4 / 2
            # Also we need g5 = (g2 + g3 + 840) / g4 to be an integer
            # Let's just iterate over g3 being a divisor.
            for g3 in range(2, num4 // 2 + 1):
                if num4 % g3 == 0:
                    g4 = num4 // g3
                    num5 = g2 + g3 + 840
                    if num5 % g4 == 0:
                        g5 = num5 // g4
                        if g5 > 1:
                            # Now we have g1, g2, g3, g4, g5. Let's check the rest.
                            g = [0] * 2026
                            g[1], g[2], g[3], g[4], g[5] = g1, g2, g3, g4, g5
                            possible = True
                            for n in range(2, 2023):
                                num = g[n] + g[n+1] + 840
                                den = g[n+2]
                                if num % den != 0:
                                    possible = False
                                    break
                                val = num // den
